114		// If force is true, remove all existing Entire hooks first
115		if force {
116			sessionStart = removeEntireHooks(sessionStart)
117			sessionEnd = removeEntireHooks(sessionEnd)
118			stop = removeEntireHooks(stop)
119			userPromptSubmit = removeEntireHooks(userPromptSubmit)
120			preToolUse = removeEntireHooks(preToolUse)
121			postToolUse = removeEntireHooks(postToolUse)
122			preCompact = removeEntireHooks(preCompact)
123		}
124	
125		// Define hook commands
126		sessionStartCmd := agent.WrapProductionSilentHookCommand("entire hooks factoryai-droid session-start")
127		sessionEndCmd := agent.WrapProductionSilentHookCommand("entire hooks factoryai-droid session-end")
128		stopCmd := agent.WrapProductionPlainTextWarningHookCommand("entire hooks factoryai-droid stop", agent.WarningFormatSingleLine)
129		userPromptSubmitCmd := agent.WrapProductionSilentHookCommand("entire hooks factoryai-droid user-prompt-submit")
130		preTaskCmd := agent.WrapProductionSilentHookCommand("entire hooks factoryai-droid pre-tool-use")
131		postTaskCmd := agent.WrapProductionSilentHookCommand("entire hooks factoryai-droid post-tool-use")
132		preCompactCmd := agent.WrapProductionSilentHookCommand("entire hooks factoryai-droid pre-compact")
133	
134		// Drop Entire hooks left by older versions before adding the current ones,
135		// so a stale command (e.g. the removed local-dev launcher) does not survive
136		// alongside them. Unconditional: a plain `entire enable` must migrate too.
137		staleDropped := false
138		drop := func(matchers []FactoryHookMatcher, want ...string) []FactoryHookMatcher {
139			out, dropped := dropStaleEntireHooks(matchers, want...)
140			if dropped {
141				staleDropped = true
