144		}
145		sessionStart = drop(sessionStart, sessionStartCmd, userPromptSubmitCmd)
146		sessionEnd = drop(sessionEnd, sessionEndCmd)
147		stop = drop(stop, stopCmd)
148		userPromptSubmit = drop(userPromptSubmit, userPromptSubmitCmd)
149		preToolUse = drop(preToolUse, preTaskCmd)
150		postToolUse = drop(postToolUse, postTaskCmd)
151		preCompact = drop(preCompact, preCompactCmd)
152	
153		count := 0
154	
155		// Add hooks if they don't exist
156		if !hookCommandExists(sessionStart, sessionStartCmd) {
157			sessionStart = addHookToMatcher(sessionStart, "", sessionStartCmd)
158			count++
159		}
