166			count++
167		}
168		if !hookCommandExists(sessionEnd, sessionEndCmd) {
169			sessionEnd = addHookToMatcher(sessionEnd, "", sessionEndCmd)
170			count++
171		}
172		if !hookCommandExists(stop, stopCmd) {
173			stop = addHookToMatcher(stop, "", stopCmd)
174			count++
175		}
176		if !hookCommandExists(userPromptSubmit, userPromptSubmitCmd) {
177			userPromptSubmit = addHookToMatcher(userPromptSubmit, "", userPromptSubmitCmd)
178			count++
179		}
180		if !hookCommandExistsWithMatcher(preToolUse, "Task", preTaskCmd) {
181			preToolUse = addHookToMatcher(preToolUse, "Task", preTaskCmd)
182			count++
183		}
184		if !hookCommandExistsWithMatcher(postToolUse, "Task", postTaskCmd) {
185			postToolUse = addHookToMatcher(postToolUse, "Task", postTaskCmd)
