194		// `entire enable` must drop the retired metadata deny rule, not just
195		// --force. See agent.MetadataDenyRule for why it is retired.
196		permissionsChanged, err := agent.RemoveMetadataDenyRule(rawPermissions)
197		if err != nil {
198			return 0, fmt.Errorf("failed to update permissions in %s: %w", cfg.Path(), err)
199		}
