208		// Marshal modified hook types back to rawHooks
209		marshalHookType(rawHooks, "SessionStart", sessionStart)
210		marshalHookType(rawHooks, "SessionEnd", sessionEnd)
211		marshalHookType(rawHooks, "Stop", stop)
212		marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
213		marshalHookType(rawHooks, "PreToolUse", preToolUse)
214		marshalHookType(rawHooks, "PostToolUse", postToolUse)
215		marshalHookType(rawHooks, "PreCompact", preCompact)
216	
217		// Marshal hooks and update raw settings
218		hooksJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawHooks)
219		if err != nil {
220			return 0, fmt.Errorf("failed to marshal hooks: %w", err)
221		}
222		rawSettings["hooks"] = hooksJSON
223	
224		// Marshal permissions and update raw settings
225		permJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawPermissions)
226		if err != nil {
227			return 0, fmt.Errorf("failed to marshal permissions: %w", err)
228		}
229		rawSettings["permissions"] = permJSON
230	
231		// Write back to file
232		output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
233		if err != nil {
234			return 0, fmt.Errorf("failed to marshal settings: %w", err)
235		}
236	
237		// Write creates .factory with MkdirAllNoSymlink.
238		if err := cfg.Write(output, 0o600); err != nil {
239			return 0, err //nolint:wrapcheck // agent.HookConfigFile already names the file in its error
240		}
241	
242		return count, nil
243	}
244	
245	// parseHookType parses a specific hook type from rawHooks into the target slice.
246	// Silently ignores parse errors (leaves target unchanged).
247	func parseHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]FactoryHookMatcher) {
248		if data, ok := rawHooks[hookType]; ok {
249			//nolint:errcheck,gosec // Intentionally ignoring parse errors - leave target as nil/empty
250			json.Unmarshal(data, target)
251		}
252	}
253	
254	// marshalHookType marshals a hook type back to rawHooks.
255	// If the slice is empty, removes the key from rawHooks.
256	func marshalHookType(rawHooks map[string]json.RawMessage, hookType string, matchers []FactoryHookMatcher) {
257		if len(matchers) == 0 {
258			delete(rawHooks, hookType)
259			return
260		}
261		data, err := jsonutil.MarshalWithNoHTMLEscape(matchers)
262		if err != nil {
263			return // Silently ignore marshal errors (shouldn't happen)
264		}
265		rawHooks[hookType] = data
266	}
267	
268	// UninstallHooks removes Entire hooks from Factory AI Droid settings.
269	func (f *FactoryAIDroidAgent) UninstallHooks(ctx context.Context) error {
270		cfg, err := factoryHookConfig(ctx)
271		if err != nil {
272			return err
273		}
274		data, err := cfg.Read()
275		if err != nil {
276			// An absent file means nothing to uninstall; an unreadable one does not.
277			// Collapsing both leaves hooks on disk while reporting success.
278			if errors.Is(err, os.ErrNotExist) {
279				return nil
280			}
281			return fmt.Errorf("read %s: %w", cfg.Path(), err)
282		}
283	
284		var rawSettings map[string]json.RawMessage
285		if err := json.Unmarshal(data, &rawSettings); err != nil {
286			return fmt.Errorf("failed to parse settings.json: %w", err)
287		}
288	
289		// rawHooks preserves unknown hook types
290		var rawHooks map[string]json.RawMessage
291		if hooksRaw, ok := rawSettings["hooks"]; ok {
292			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
293				return fmt.Errorf("failed to parse hooks: %w", err)
294			}
295		}
296		if rawHooks == nil {
297			rawHooks = make(map[string]json.RawMessage)
298		}
299	
300		// Parse only the hook types we need to modify
301		var sessionStart, sessionEnd, stop, userPromptSubmit, preToolUse, postToolUse, preCompact []FactoryHookMatcher
302		parseHookType(rawHooks, "SessionStart", &sessionStart)
303		parseHookType(rawHooks, "SessionEnd", &sessionEnd)
304		parseHookType(rawHooks, "Stop", &stop)
305		parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
306		parseHookType(rawHooks, "PreToolUse", &preToolUse)
307		parseHookType(rawHooks, "PostToolUse", &postToolUse)
308		parseHookType(rawHooks, "PreCompact", &preCompact)
309	
310		// Remove Entire hooks from all hook types
311		sessionStart = removeEntireHooks(sessionStart)
312		sessionEnd = removeEntireHooks(sessionEnd)
313		stop = removeEntireHooks(stop)
314		userPromptSubmit = removeEntireHooks(userPromptSubmit)
315		preToolUse = removeEntireHooks(preToolUse)
316		postToolUse = removeEntireHooks(postToolUse)
317		preCompact = removeEntireHooks(preCompact)
318	
319		// Marshal modified hook types back to rawHooks
320		marshalHookType(rawHooks, "SessionStart", sessionStart)
321		marshalHookType(rawHooks, "SessionEnd", sessionEnd)
322		marshalHookType(rawHooks, "Stop", stop)
323		marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
324		marshalHookType(rawHooks, "PreToolUse", preToolUse)
325		marshalHookType(rawHooks, "PostToolUse", postToolUse)
326		marshalHookType(rawHooks, "PreCompact", preCompact)
327	
328		// Also remove the metadata deny rule from permissions
329		var rawPermissions map[string]json.RawMessage
330		if permRaw, ok := rawSettings["permissions"]; ok {
331			if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
332				// If parsing fails, just skip permissions cleanup
333				rawPermissions = nil
334			}
335		}
336	
337		if rawPermissions != nil {
338			// Same removal InstallHooks now performs; best-effort so a marshal
339			// failure cannot abort the rest of the hook removal.
340			_, _ = agent.RemoveMetadataDenyRule(rawPermissions) //nolint:errcheck // best-effort during uninstall
341	
342			// If permissions is empty, remove it entirely
343			if len(rawPermissions) > 0 {
344				permJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawPermissions)
345				if err == nil {
346					rawSettings["permissions"] = permJSON
347				}
348			} else {
349				delete(rawSettings, "permissions")
350			}
351		}
352	
353		// Marshal hooks back (preserving unknown hook types)
354		if len(rawHooks) > 0 {
355			hooksJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawHooks)
356			if err != nil {
357				return fmt.Errorf("failed to marshal hooks: %w", err)
358			}
359			rawSettings["hooks"] = hooksJSON
360		} else {
361			delete(rawSettings, "hooks")
362		}
363	
364		// Write back
365		output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
366		if err != nil {
367			return fmt.Errorf("failed to marshal settings: %w", err)
368		}
369		if err := cfg.Write(output, 0o600); err != nil {
370			return err //nolint:wrapcheck // agent.HookConfigFile already names the file in its error
371		}
372		return nil
373	}
374	
375	// AreHooksInstalled checks if Entire hooks are installed.
376	//
377	// A missing config file is an answer, not a failure: that file is where the
378	// state lives, so its absence means no hooks. Anything that stops us reading the
379	// answer — an unreadable file, malformed config — is returned as an error, since
380	// "we could not tell" and "there are none" are different things to a caller
381	// deciding whether hooks can be left alone.
382	func (f *FactoryAIDroidAgent) AreHooksInstalled(ctx context.Context) (bool, error) {
383		cfg, err := factoryHookConfig(ctx)
384		if err != nil {
385			return false, err
386		}
387		data, err := cfg.Read()
388		if errors.Is(err, os.ErrNotExist) {
389			return false, nil
390		}
391		if err != nil {
392			logging.Warn(ctx, "factoryai-droid: failed to read settings file", "path", cfg.Path(), "err", err)
393			return false, fmt.Errorf("read %s: %w", cfg.Path(), err)
394		}
395	
396		var settings FactorySettings
397		if err := json.Unmarshal(data, &settings); err != nil {
398			logging.Warn(ctx, "factoryai-droid: failed to parse settings file", "path", cfg.Path(), "err", err)
399			return false, fmt.Errorf("parse hook config: %w", err)
400		}
401	
402		// Check for at least one of our hooks (production, wrapped, or local-dev format)
403		return hasEntireHook(settings.Hooks.Stop), nil
404	}
405	
406	// Helper functions for hook management
407	
408	func hookCommandExists(matchers []FactoryHookMatcher, command string) bool {
409		for _, matcher := range matchers {
410			for _, hook := range matcher.Hooks {
411				if hook.Command == command {
412					return true
413				}
414			}
415		}
416		return false
417	}
418	
419	func hasEntireHook(matchers []FactoryHookMatcher) bool {
420		for _, matcher := range matchers {
421			for _, hook := range matcher.Hooks {
422				if isEntireHook(hook.Command) {
423					return true
424				}
425			}
426		}
427		return false
428	}
429	
430	func hookCommandExistsWithMatcher(matchers []FactoryHookMatcher, matcherName, command string) bool {
431		for _, matcher := range matchers {
432			if matcher.Matcher == matcherName {
433				for _, hook := range matcher.Hooks {
434					if hook.Command == command {
435						return true
436					}
437				}
438			}
439		}
440		return false
441	}
442	
443	func addHookToMatcher(matchers []FactoryHookMatcher, matcherName, command string) []FactoryHookMatcher {
444		entry := FactoryHookEntry{Type: "command", Command: command}
445		for i := range matchers {
446			if matchers[i].Matcher == matcherName {
447				matchers[i].Hooks = append(matchers[i].Hooks, entry)
448				return matchers
449			}
450		}
451		return append(matchers, FactoryHookMatcher{Matcher: matcherName, Hooks: []FactoryHookEntry{entry}})
452	}
453	
454	// isEntireHook checks if a command is an Entire hook
455	func isEntireHook(command string) bool {
456		return agent.IsManagedHookCommand(command)
457	}
458	
459	// dropStaleEntireHooks removes Entire-owned hooks whose command is not one of
460	// want, per matcher, pruning matchers left with no hooks. want is a set because
461	// one hook list can hold several Entire commands (SessionStart carries both
462	// session-start and user-prompt-submit). See agent.DropStaleManagedHooks for why
463	// this runs on every install and why the dropped flag matters.
464	func dropStaleEntireHooks(matchers []FactoryHookMatcher, want ...string) ([]FactoryHookMatcher, bool) {
465		result := make([]FactoryHookMatcher, 0, len(matchers))
466		dropped := false
467		for _, matcher := range matchers {
468			kept, d := agent.DropStaleManagedHooks(matcher.Hooks, hookEntryCommand, want)
469			if d {
470				dropped = true
471			}
472			if len(kept) > 0 {
473				matcher.Hooks = kept
474				result = append(result, matcher)
475			}
476		}
477		if !dropped {
478			return matchers, false
479		}
480		return result, true
481	}
482	
483	// hookEntryCommand reads the command off a hook entry for the shared helpers.
484	func hookEntryCommand(e FactoryHookEntry) string { return e.Command }
485	
486	// removeEntireHooks removes all Entire hooks from a list of matchers (for simple
487	// hooks like Stop). It is dropStaleEntireHooks with an empty want set: nothing is
488	// wanted, so every managed hook is stale.
489	func removeEntireHooks(matchers []FactoryHookMatcher) []FactoryHookMatcher {
490		out, _ := dropStaleEntireHooks(matchers)
491		return out
492	}
493	
494	// PermissionConfig implements agent.PermissionConfigOwner so the shared
495	// retired-deny-rule diagnostics and repair can reach .factory/settings.json
496	// without knowing Factory Droid's layout.
497	func (f *FactoryAIDroidAgent) PermissionConfig(ctx context.Context) (*agent.HookConfigFile, error) {
498		return factoryHookConfig(ctx)
499	}
